-- 65 Two Views of the Railway: three cameras, each drawing onto its own
-- part of the screen (`screen_rect`, changed with Camera.set_screen_rect).
-- This only moves them: each follows what it watches and turns with it, so
-- the train and the car point up their halves. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/65-two-views-of-the-railway.scene"
local captions, turning = true, true
local layout = 1
local train, car, train_cam, car_cam, map_cam, status
local LAYOUTS = {
    { { 0.0, 0.0, 0.497, 1.0 }, { 0.503, 0.0, 0.497, 1.0 }, { 0.38, 0.68, 0.24, 0.28 } },
    { { 0.0, 0.0, 1.0, 0.496 }, { 0.0, 0.504, 1.0, 0.496 }, { 0.74, 0.36, 0.24, 0.28 } },
}

function init(entity)
    train = Entity.find_by_name("Engine")
    car = Entity.find_by_name("Car2")
    train_cam = Entity.find_by_name("TrainCam")
    car_cam = Entity.find_by_name("CarCam")
    map_cam = Entity.find_by_name("MapCam")
    status = Entity.find_by_name("Status")
end

local function apply()
    local l = LAYOUTS[layout]
    Camera.set_screen_rect(train_cam, l[1][1], l[1][2], l[1][3], l[1][4])
    Camera.set_screen_rect(car_cam, l[2][1], l[2][2], l[2][3], l[2][4])
    Camera.set_screen_rect(map_cam, l[3][1], l[3][2], l[3][3], l[3][4])
end

local function follow(cam, what)
    if not (cam and what) then return end
    local x, y = Transform.get_world_position(what)
    Transform.set_position(cam, x, y)
    -- A camera turned anticlockwise swings the world clockwise: turned by
    -- the heading less a quarter, what it follows points up.
    Transform.set_rotation(cam, turning and (Transform.get_world_rotation(what) - math.pi / 2) or 0)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("1") then layout = 1; apply() end
    if Input.is_key_just_pressed("2") then layout = 2; apply() end
    if Input.is_key_just_pressed("Space") then turning = not turning end
    follow(train_cam, train)
    follow(car_cam, car)
    if status then
        UI.set_text(status, (layout == 1 and "side by side" or "top / bottom") .. (turning and "   turning" or "   north up"))
    end
end
